package transport

import (
	"cmp"
	"context"
	"fmt"
	"slices"
	"strconv"
	"strings"
	"time"
	_ "time/tzdata" // the image is FROM scratch and has no zoneinfo

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	commonv1 "horkilion/gen/common/v1"
	transportv1 "horkilion/gen/transport/v1"
	"horkilion/internal/dataset"
	"horkilion/internal/synth"
)

// Synthetic is the provider "synthetic": real airports, stations and routes
// from the data snapshot, schedules and fares generated by the synth rules.
// A journey id encodes the route, the date and the departure, so GetOffer
// rebuilds exactly the journey the search returned.
type Synthetic struct {
	transportv1.UnimplementedTransportServiceServer
	data *dataset.Data
}

func NewSynthetic(data *dataset.Data) *Synthetic { return &Synthetic{data: data} }

const (
	// A connection may be at most this much longer than the great circle.
	maxDetour = 1.3
	// Hours between the first and the last flight of a day.
	firstFlightHour, lastFlightHour = 6, 22
	refundableMarkup                = 1.25
)

// Carriers by the country of the departure airport.
var carriers = map[string][]string{
	"RU": {"SU", "S7", "U6"}, "BY": {"B2"}, "KZ": {"KC", "DV"}, "TR": {"TK", "PC"}, "AE": {"EK", "FZ"},
	"EG": {"MS"}, "CN": {"CA"}, "FR": {"AF"}, "GE": {"A9"},
}

func (s *Synthetic) SearchJourneys(_ context.Context, req *transportv1.SearchJourneysRequest) (*transportv1.SearchJourneysResponse, error) {
	date, err := time.Parse(time.DateOnly, req.GetDate())
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "date must be YYYY-MM-DD")
	}
	party, err := synth.ParseParty(req.GetPassengers())
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "passengers."+err.Error())
	}
	from, to := s.city(req.GetOrigin()), s.city(req.GetDestination())
	if from != nil && from == to {
		return nil, status.Error(codes.InvalidArgument, "origin and destination are the same city")
	}
	if from == nil || to == nil {
		// Not in the catalog: an empty answer, the agent tells the user.
		return &transportv1.SearchJourneysResponse{}, nil
	}
	modes := req.GetModes()
	var out []*transportv1.Journey
	if len(modes) == 0 || slices.Contains(modes, transportv1.Mode_MODE_AIR) {
		for _, a := range from.Airports {
			for _, b := range to.Airports {
				out = append(out, s.flights(a, b, date, party)...)
			}
		}
	}
	if len(modes) == 0 || slices.Contains(modes, transportv1.Mode_MODE_RAIL) {
		for _, a := range from.Stations {
			for _, b := range to.Stations {
				out = append(out, s.trains(a, b, date, party)...)
			}
		}
	}
	slices.SortFunc(out, func(a, b *transportv1.Journey) int {
		return cmp.Or(strings.Compare(a.Segments[0].DepartAt, b.Segments[0].DepartAt), strings.Compare(a.Id, b.Id))
	})
	return &transportv1.SearchJourneysResponse{Journeys: out}, nil
}

func (s *Synthetic) GetOffer(_ context.Context, req *transportv1.GetOfferRequest) (*transportv1.Journey, error) {
	party, err := synth.ParseParty(req.GetPassengers())
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "passengers."+err.Error())
	}
	// mode:from:to:date:index
	parts := strings.Split(req.GetJourneyId(), ":")
	if len(parts) != 5 {
		return nil, status.Error(codes.NotFound, "unknown journey id")
	}
	date, err := time.Parse(time.DateOnly, parts[3])
	if err != nil {
		return nil, status.Error(codes.NotFound, "unknown journey id")
	}
	var day []*transportv1.Journey
	switch parts[0] {
	case "air":
		day = s.flights(parts[1], parts[2], date, party)
	case "rail":
		day = s.trains(parts[1], parts[2], date, party)
	}
	for _, j := range day {
		if j.Id == req.GetJourneyId() {
			return j, nil
		}
	}
	return nil, status.Error(codes.NotFound, "unknown journey id")
}

// city resolves a city by name or id, an IATA code or a station code.
func (s *Synthetic) city(name string) *dataset.City {
	if c := s.data.FindCity(name); c != nil {
		return c
	}
	if a := s.data.AirportByIATA[strings.ToUpper(strings.TrimSpace(name))]; a != nil {
		return s.data.CityByID[a.CityID]
	}
	if st := s.data.StationByCode[dataset.Fold(name)]; st != nil {
		return s.data.CityByID[st.CityID]
	}
	return nil
}

// flights are the journeys of one day between two airports: one to three
// departures, direct or through the hub with the smallest detour.
func (s *Synthetic) flights(fromIATA, toIATA string, date time.Time, p synth.Party) []*transportv1.Journey {
	route, ok := s.data.Route(fromIATA, toIATA)
	if !ok {
		return nil
	}
	cal := s.data.Calibration
	a, b := s.data.AirportByIATA[fromIATA], s.data.AirportByIATA[toIATA]
	legs := []*dataset.Airport{a, b}
	if !route.Direct {
		hub := s.hub(a, b)
		if hub == nil {
			return nil
		}
		legs = []*dataset.Airport{a, hub, b}
	}
	day := date.Format(time.DateOnly)
	r := synth.Rand("flights", fromIATA, toIATA, day)
	fleet := carriers[a.CountryCode]
	if len(fleet) == 0 {
		fleet = carriers[b.CountryCode]
	}
	if len(fleet) == 0 {
		fleet = []string{"ZZ"}
	}
	hours := r.Perm(lastFlightHour - firstFlightHour)[:1+r.IntN(3)]
	slices.Sort(hours)

	var out []*transportv1.Journey
	for i, h := range hours {
		id := fmt.Sprintf("air:%s:%s:%s:%d", fromIATA, toIATA, day, i)
		carrier := fleet[r.IntN(len(fleet))]
		depart := time.Date(date.Year(), date.Month(), date.Day(), firstFlightHour+h, 5*r.IntN(12), 0, 0, zone(a.Timezone))
		var segs []*transportv1.Segment
		at := depart
		for k := 0; k+1 < len(legs); k++ {
			if k > 0 {
				at = at.Add(time.Duration(cal.Airfare.TransferMinutes) * time.Minute)
			}
			x, y := legs[k], legs[k+1]
			arrive := at.Add(time.Duration(synth.FlightMinutes(synth.Haversine(x.Lat, x.Lon, y.Lat, y.Lon))) * time.Minute)
			segs = append(segs, &transportv1.Segment{
				Mode: transportv1.Mode_MODE_AIR, Carrier: carrier, Number: carrier + strconv.Itoa(100+r.IntN(9000)),
				From: airportPlace(x), To: airportPlace(y),
				DepartAt: at.In(zone(x.Timezone)).Format(time.RFC3339), ArriveAt: arrive.In(zone(y.Timezone)).Format(time.RFC3339),
			})
			at = arrive
		}
		refundable := r.IntN(3) == 0
		price := float64(synth.AirFareRub(cal, route, p, date)) * synth.Noise(0.9, 1.15, "flight", id)
		if refundable {
			price *= refundableMarkup
		}
		out = append(out, &transportv1.Journey{
			Id: id, Segments: segs, DurationMinutes: int32(at.Sub(depart).Minutes()), Transfers: int32(len(segs) - 1),
			BaggageIncluded: r.IntN(2) == 0, Refundable: refundable, PriceRub: synth.RoundRub(price),
			Sources: append(synth.Sources(s.data, "places", "ourairports"), synth.Sources(s.data, "schedule,price", "synthetic")...),
		})
	}
	return out
}

// hub is the airport that makes the shortest connection, within maxDetour.
// impulse: the hub is picked by geometry among snapshot airports, use real connection hubs from the data when DS adds them to routes.
func (s *Synthetic) hub(a, b *dataset.Airport) *dataset.Airport {
	direct := synth.Haversine(a.Lat, a.Lon, b.Lat, b.Lon)
	var best *dataset.Airport
	bestKm := direct * maxDetour
	for i := range s.data.Airports {
		h := &s.data.Airports[i]
		if h.IATA == a.IATA || h.IATA == b.IATA || !h.Scheduled {
			continue
		}
		if km := synth.Haversine(a.Lat, a.Lon, h.Lat, h.Lon) + synth.Haversine(h.Lat, h.Lon, b.Lat, b.Lon); km < bestKm {
			best, bestKm = h, km
		}
	}
	return best
}

// trains are the departures of one day between two stations from the
// snapshot timetable.
func (s *Synthetic) trains(fromCode, toCode string, date time.Time, p synth.Party) []*transportv1.Journey {
	route, ok := s.data.Rail(fromCode, toCode)
	if !ok {
		return nil
	}
	a, b := s.data.StationByCode[fromCode], s.data.StationByCode[toCode]
	ca, cb := s.data.CityByID[a.CityID], s.data.CityByID[b.CityID]
	day := date.Format(time.DateOnly)
	var out []*transportv1.Journey
	for i, dep := range route.Departures {
		t, err := time.Parse("15:04", dep)
		if err != nil {
			continue // dataset.Load already checks the format
		}
		depart := time.Date(date.Year(), date.Month(), date.Day(), t.Hour(), t.Minute(), 0, 0, zone(ca.Timezone))
		arrive := depart.Add(time.Duration(route.DurationMin) * time.Minute)
		train := route.TrainNumbers[i]
		out = append(out, &transportv1.Journey{
			Id: fmt.Sprintf("rail:%s:%s:%s:%d", fromCode, toCode, day, i),
			Segments: []*transportv1.Segment{{
				Mode: transportv1.Mode_MODE_RAIL, Carrier: railCarrier(ca.CountryCode), Number: train,
				From: stationPlace(a, ca), To: stationPlace(b, cb),
				DepartAt: depart.Format(time.RFC3339), ArriveAt: arrive.In(zone(cb.Timezone)).Format(time.RFC3339),
			}},
			DurationMinutes: int32(route.DurationMin), BaggageIncluded: true, Refundable: true,
			PriceRub: synth.RailFareRub(s.data.Calibration, route, train, p, date),
			// rail_routes carry no sources (CFC-3): the schedule comes from Yandex Rasp in the real snapshot and
			// from test values in the backend one; synth.Sources keeps whichever the registry lists.
			Sources: append(synth.Sources(s.data, "schedule", "yandex-rasp", "testdata"), synth.Sources(s.data, "price", "synthetic")...),
		})
	}
	return out
}

func railCarrier(country string) string {
	if country == "RU" {
		return "ФПК"
	}
	return "Железная дорога"
}

func zone(name string) *time.Location {
	if loc, err := time.LoadLocation(name); err == nil {
		return loc
	}
	return time.UTC
}

func airportPlace(a *dataset.Airport) *commonv1.Place {
	return &commonv1.Place{
		Id: a.IATA, Name: a.Name, Kind: commonv1.Place_KIND_AIRPORT, CountryCode: a.CountryCode,
		Point: &commonv1.GeoPoint{Lat: a.Lat, Lon: a.Lon}, Timezone: a.Timezone, Code: a.IATA,
	}
}

func stationPlace(st *dataset.Station, c *dataset.City) *commonv1.Place {
	return &commonv1.Place{
		Id: st.Code, Name: st.Name, Kind: commonv1.Place_KIND_STATION, CountryCode: c.CountryCode,
		Point: &commonv1.GeoPoint{Lat: st.Lat, Lon: st.Lon}, Timezone: c.Timezone, Code: st.Code,
	}
}
